<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\BusinessSetting;use App\Models\Customer;use App\Models\CustomerLedger;use App\Models\InventoryStock;use App\Models\Payment;use App\Models\Product;use App\Models\SalesInvoice;use App\Models\SalesReturn;use App\Support\BusinessAccess;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class SalesInvoiceController extends Controller{
 public function index(Request $r){BusinessAccess::requireRole($r,['owner','manager','accountant','salesperson','super_admin']);$q=SalesInvoice::with('customer')->where('business_id',BusinessAccess::id($r));BusinessAccess::scopeBranch($q,$r);if($r->user()->role==='salesperson')$q->where('user_id',$r->user()->id);return response()->json(['data'=>$q->latest('invoice_date')->paginate($r->integer('per_page',20))]);}
 public function show(Request $r,SalesInvoice $invoice){$this->authorizeInvoice($r,$invoice);return response()->json(['data'=>$invoice->load(['items.product','customer','branch','returns.items'])]);}
 public function store(Request $r){$business=BusinessAccess::id($r);$data=$r->validate(['branch_id'=>['required','integer','exists:branches,id'],'customer_id'=>['required','integer','exists:customers,id'],'invoice_date'=>['nullable','date'],'discount'=>['nullable','numeric','min:0'],'vat'=>['nullable','numeric','min:0'],'paid_amount'=>['nullable','numeric','min:0'],'payment_method'=>['nullable','in:cash,bank,bkash,nagad'],'transaction_id'=>['nullable','string','max:100'],'notes'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','integer','exists:products,id'],'items.*.quantity'=>['required','numeric','gt:0'],'items.*.unit_price'=>['nullable','numeric','min:0'],'items.*.discount'=>['nullable','numeric','min:0']]);BusinessAccess::branch($r,$data['branch_id']);return DB::transaction(function()use($data,$r,$business){$customer=Customer::where('business_id',$business)->findOrFail($data['customer_id']);$subtotal=0;$prepared=[];foreach($data['items'] as $row){$product=Product::where('business_id',$business)->findOrFail($row['product_id']);$stock=InventoryStock::where('branch_id',$data['branch_id'])->where('product_id',$product->id)->lockForUpdate()->firstOrCreate(['branch_id'=>$data['branch_id'],'product_id'=>$product->id],['quantity'=>0,'reorder_level'=>0]);abort_if($stock->quantity<$row['quantity'],422,"Insufficient stock for {$product->name}.");$price=$row['unit_price']??$product->selling_price;$line=($price*$row['quantity'])-($row['discount']??0);abort_if($line<0,422,'Line discount cannot exceed line value.');$subtotal+=$line;$prepared[]=compact('product','stock','price','line','row');}$discount=$data['discount']??0;$vat=$data['vat']??0;$total=$subtotal-$discount+$vat;abort_if($total<0,422,'Invoice total cannot be negative.');$paid=$data['paid_amount']??0;abort_if($paid>$total,422,'Paid amount cannot exceed invoice total.');$method=$data['payment_method']??'cash';if($paid>0&&$method!=='cash')abort_if(empty($data['transaction_id']),422,'Transaction ID is required for digital payments.');$newDue=$total-$paid;abort_if($customer->credit_limit>0&&$customer->current_due+$newDue>$customer->credit_limit,422,'Customer credit limit exceeded.');$prefix=BusinessSetting::where('business_id',$business)->where('key','invoice_prefix')->value('value')?:'INV';$number=$prefix.'-'.now()->format('YmdHis').'-'.random_int(100,999);$invoice=SalesInvoice::create(['business_id'=>$business,'branch_id'=>$data['branch_id'],'customer_id'=>$customer->id,'user_id'=>$r->user()->id,'invoice_number'=>$number,'invoice_date'=>$data['invoice_date']??today(),'subtotal'=>$subtotal,'discount'=>$discount,'vat'=>$vat,'grand_total'=>$total,'paid_amount'=>$paid,'payment_status'=>$paid==0?'due':($paid==$total?'paid':'partial'),'status'=>'completed','notes'=>$data['notes']??null]);foreach($prepared as $item){$item['stock']->decrement('quantity',$item['row']['quantity']);$invoice->items()->create(['product_id'=>$item['product']->id,'product_name'=>$item['product']->name,'quantity'=>$item['row']['quantity'],'unit_price'=>$item['price'],'unit_cost'=>$item['product']->purchase_price,'discount'=>$item['row']['discount']??0,'line_total'=>$item['line']]);}if($paid>0)Payment::create(['business_id'=>$business,'branch_id'=>$invoice->branch_id,'customer_id'=>$customer->id,'sales_invoice_id'=>$invoice->id,'user_id'=>$r->user()->id,'receipt_number'=>'RCT-'.now()->format('YmdHis').'-'.random_int(100,999),'collection_date'=>$invoice->invoice_date,'amount'=>$paid,'method'=>$method,'transaction_id'=>$data['transaction_id']??null,'notes'=>'Payment received with '.$number,'status'=>'completed']);if($newDue>0){$balance=$customer->current_due+$newDue;$customer->update(['current_due'=>$balance,'due_since'=>$customer->due_since??today()]);CustomerLedger::create(['customer_id'=>$customer->id,'branch_id'=>$invoice->branch_id,'sales_invoice_id'=>$invoice->id,'entry_date'=>$invoice->invoice_date,'type'=>'sale','reference'=>$number,'debit'=>$newDue,'credit'=>0,'balance'=>$balance]);}return response()->json(['data'=>$invoice->load('items')],201);});}
 public function cancel(Request $r,SalesInvoice $invoice){$this->authorizeInvoice($r,$invoice);abort_if($invoice->status!=='completed',422,'Invoice is already cancelled.');abort_if($invoice->paid_amount>0,422,'A paid invoice requires a refund/return before cancellation.');return DB::transaction(function()use($invoice){foreach($invoice->items as $item){$stock=InventoryStock::firstOrCreate(['branch_id'=>$invoice->branch_id,'product_id'=>$item->product_id],['quantity'=>0,'reorder_level'=>0]);$stock->increment('quantity',$item->quantity);}$customer=$invoice->customer;$balance=max(0,$customer->current_due-$invoice->grand_total);$customer->update(['current_due'=>$balance,'due_since'=>$balance==0?null:$customer->due_since]);CustomerLedger::create(['customer_id'=>$customer->id,'branch_id'=>$invoice->branch_id,'sales_invoice_id'=>$invoice->id,'entry_date'=>today(),'type'=>'cancellation','reference'=>$invoice->invoice_number,'debit'=>0,'credit'=>$invoice->grand_total,'balance'=>$balance]);$invoice->update(['status'=>'cancelled','payment_status'=>'cancelled']);return response()->json(['data'=>$invoice->fresh('items')]);});}
 public function returns(Request $r){$q=SalesReturn::with(['customer','invoice:id,invoice_number','items.product'])->where('business_id',BusinessAccess::id($r));BusinessAccess::scopeBranch($q,$r);return response()->json(['data'=>$q->latest('return_date')->paginate($r->integer('per_page',20))]);}
 public function returnSale(Request $r,SalesInvoice $invoice){$this->authorizeInvoice($r,$invoice);abort_if($invoice->status!=='completed',422,'Only completed invoices can be returned.');$data=$r->validate(['return_date'=>['nullable','date'],'refund_method'=>['nullable','in:cash,bank,bkash,nagad'],'reason'=>['nullable','string','max:500'],'items'=>['required','array','min:1'],'items.*.product_id'=>['required','integer','exists:products,id'],'items.*.quantity'=>['required','numeric','gt:0']]);return DB::transaction(function()use($r,$invoice,$data){$prepared=[];$total=0;$factor=$invoice->subtotal>0?(float)$invoice->grand_total/(float)$invoice->subtotal:1;foreach($data['items'] as $row){$line=$invoice->items()->where('product_id',$row['product_id'])->firstOrFail();$already=DB::table('sales_return_items')->join('sales_returns','sales_returns.id','=','sales_return_items.sales_return_id')->where('sales_returns.sales_invoice_id',$invoice->id)->where('sales_return_items.product_id',$row['product_id'])->sum('sales_return_items.quantity');abort_if($already+$row['quantity']>$line->quantity,422,'Return quantity exceeds sold quantity.');$amount=round(((float)$line->line_total/(float)$line->quantity)*$row['quantity']*$factor,2);$total+=$amount;$prepared[]=compact('line','row','amount');}$customer=$invoice->customer;$dueReduction=min((float)$customer->current_due,$total);$refund=$total-$dueReduction;abort_if($refund>0&&empty($data['refund_method']),422,'Refund method is required for a paid return.');$return=SalesReturn::create(['business_id'=>$invoice->business_id,'branch_id'=>$invoice->branch_id,'customer_id'=>$invoice->customer_id,'sales_invoice_id'=>$invoice->id,'user_id'=>$r->user()->id,'return_number'=>'SRET-'.now()->format('YmdHis').'-'.random_int(100,999),'return_date'=>$data['return_date']??today(),'total_amount'=>$total,'due_reduction'=>$dueReduction,'refund_amount'=>$refund,'refund_method'=>$refund>0?$data['refund_method']:null,'reason'=>$data['reason']??null]);foreach($prepared as $item){InventoryStock::firstOrCreate(['branch_id'=>$invoice->branch_id,'product_id'=>$item['line']->product_id],['quantity'=>0,'reorder_level'=>0])->increment('quantity',$item['row']['quantity']);$return->items()->create(['product_id'=>$item['line']->product_id,'quantity'=>$item['row']['quantity'],'unit_price'=>$item['line']->unit_price,'unit_cost'=>$item['line']->unit_cost,'line_total'=>$item['amount']]);}if($dueReduction>0){$balance=$customer->current_due-$dueReduction;$customer->update(['current_due'=>$balance,'due_since'=>$balance==0?null:$customer->due_since]);CustomerLedger::create(['customer_id'=>$customer->id,'branch_id'=>$invoice->branch_id,'sales_invoice_id'=>$invoice->id,'entry_date'=>$return->return_date,'type'=>'return','reference'=>$return->return_number,'debit'=>0,'credit'=>$dueReduction,'balance'=>$balance,'notes'=>$return->reason]);}$returned=DB::table('sales_return_items')->join('sales_returns','sales_returns.id','=','sales_return_items.sales_return_id')->where('sales_returns.sales_invoice_id',$invoice->id)->sum('sales_return_items.quantity');$sold=$invoice->items()->sum('quantity');$invoice->update(['return_status'=>$returned>=$sold?'returned':'partial']);return response()->json(['data'=>$return->load(['items.product','customer'])],201);});}
 private function authorizeInvoice(Request $r,SalesInvoice $invoice):void{abort_unless($invoice->business_id===BusinessAccess::id($r),403);BusinessAccess::branch($r,$invoice->branch_id);if($r->user()->role==='salesperson')abort_unless($invoice->user_id===$r->user()->id,403,'You can only access your own invoices.');}
}
